-- Database-wide optimistic revision. Covers all writers, including native D1 batches.
CREATE TABLE "D1TxnRevision" (
 "id" INTEGER NOT NULL PRIMARY KEY CHECK("id"=1),
 "version" INTEGER NOT NULL CHECK("version">=0 AND "version"<9007199254740991)
);
INSERT INTO "D1TxnRevision" ("id","version") VALUES (1,0);
CREATE TABLE "D1TxnGuard" (
 "id" TEXT NOT NULL PRIMARY KEY,
 "valid" INTEGER NOT NULL CONSTRAINT D1_ATOMIC_SNAPSHOT CHECK("valid"=1)
);
-- Provider-neutral identity directory only. Never stores passwords or session tokens.
CREATE TABLE "D1Identity" (
 "id" TEXT NOT NULL PRIMARY KEY,
 "email" TEXT NOT NULL COLLATE NOCASE,
 "email_confirmed_at" DATETIME,
 "created_at" DATETIME NOT NULL,
 "last_sign_in_at" DATETIME,
 "provider" TEXT NOT NULL DEFAULT 'supabase-source'
);
CREATE UNIQUE INDEX "D1Identity_email_key" ON "D1Identity"("email");
